WITH v(subject, exam_board, level, topic_id, topic_name, front, back, ord) AS (VALUES
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What are the four processes of coastal erosion?', 'Hydraulic action, abrasion, attrition and solution.', 1),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is hydraulic action?', 'Waves force air into cracks in the cliff, which breaks the rock apart.', 2),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is abrasion?', 'Rocks carried by waves are thrown against the cliff, wearing it away.', 3),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is attrition?', 'Rocks carried by waves knock against each other, becoming smaller and rounder.', 4),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is solution?', 'Seawater dissolves soluble rocks such as chalk and limestone.', 5),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is longshore drift?', 'The movement of sediment along the coast by waves approaching at an angle.', 6),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is the swash?', 'The movement of water up the beach after a wave breaks.', 7),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is the backwash?', 'The movement of water back down the beach under gravity.', 8),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is a constructive wave?', 'A low, gentle wave with a strong swash and weak backwash, which builds up beaches.', 9),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is a destructive wave?', 'A tall, steep wave with a weak swash and strong backwash, which erodes beaches.', 10),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is fetch?', 'The distance over which the wind blows across open water, affecting wave size.', 11),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'How is a headland formed?', 'Resistant rock erodes more slowly than softer rock, leaving land sticking out into the sea.', 12),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'How is a bay formed?', 'Softer rock is eroded more quickly, forming a curved inlet between headlands.', 13),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'How is a stack formed?', 'Waves erode a crack into a cave, then an arch; the arch roof collapses, leaving a stack.', 14),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is a stump?', 'The remains of a stack after it has been eroded further.', 15),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is a wave-cut platform?', 'A flat area of rock at the base of a cliff, left as the cliff retreats through erosion.', 16),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'How is a spit formed?', 'Longshore drift carries sediment past a bend in the coastline, where it is deposited in the sea.', 17),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is a bar?', 'A spit that grows across a bay, joining two headlands and sometimes trapping a lagoon.', 18),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is a beach?', 'A deposit of sand and shingle along the coast, formed by constructive waves.', 19),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is a sand dune?', 'A hill of sand formed when wind blows sand inland, trapped by vegetation such as marram grass.', 20),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is hard engineering?', 'Building artificial structures to control the sea, e.g. sea walls, groynes and rock armour.', 21),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is soft engineering?', 'Working with natural processes to manage the coast, e.g. beach nourishment and dune regeneration.', 22),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is a sea wall?', 'A concrete wall that reflects waves back out to sea; effective but expensive.', 23),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is a groyne?', 'A wooden or rock barrier built out to sea to trap sediment moved by longshore drift.', 24),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is rock armour?', 'Large boulders placed at the foot of a cliff to absorb wave energy.', 25),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is beach nourishment?', 'Adding sand or shingle to a beach to make it wider, absorbing wave energy.', 26),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is managed retreat?', 'Allowing the coast to erode or flood naturally in low-value areas.', 27),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is sea-level rise''s effect on coasts?', 'It increases flooding and erosion, threatening homes, farmland and habitats.', 28),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is a Shoreline Management Plan?', 'A plan that decides how each stretch of coast should be managed: hold the line, advance, retreat or do nothing.', 29),
  ('Geography', 'Eduqas', 'gcse', '1.1', 'Coastal Landscapes', 'What is mass movement at the coast?', 'The downhill movement of material under gravity, e.g. slumping and rockfalls.', 30),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is the source of a river?', 'Where the river begins, often in upland areas.', 1),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is the mouth of a river?', 'Where the river meets the sea or a lake.', 2),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is a tributary?', 'A smaller river that joins a larger one.', 3),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is a confluence?', 'The point where two rivers meet.', 4),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is a drainage basin?', 'The area of land drained by a river and its tributaries.', 5),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is a watershed?', 'The boundary of a drainage basin, usually high ground.', 6),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'How does a river change from source to mouth?', 'It becomes wider and deeper, with a greater discharge and gentler gradient.', 7),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is vertical erosion?', 'Erosion that deepens the river channel, common in the upper course.', 8),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is lateral erosion?', 'Erosion that widens the river channel, common in the middle and lower course.', 9),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What are the four types of river transportation?', 'Traction, saltation, suspension and solution.', 10),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is traction?', 'Large boulders are rolled along the river bed.', 11),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is saltation?', 'Small pebbles bounce along the river bed.', 12),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is suspension?', 'Fine particles are carried in the water.', 13),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'When does a river deposit sediment?', 'When it loses energy, e.g. when it slows down on the inside of a bend or enters the sea.', 14),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'How is a waterfall formed?', 'Soft rock beneath hard rock is eroded, creating an overhang that collapses; the waterfall retreats, leaving a gorge.', 15),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is a gorge?', 'A steep-sided valley formed as a waterfall retreats upstream.', 16),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is a V-shaped valley?', 'A steep valley in the upper course, formed by vertical erosion and weathering.', 17),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is interlocking spurs?', 'Hills that stick out alternately on either side of a river in the upper course.', 18),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'How is a meander formed?', 'Erosion on the outside of a bend (fast flow) and deposition on the inside (slow flow).', 19),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'How is an oxbow lake formed?', 'Erosion narrows the neck of a meander until the river cuts through it during a flood; deposition seals off the old loop.', 20),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is a floodplain?', 'Flat land either side of a river in the lower course, covered with deposits during floods.', 21),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is a levée?', 'A raised bank along a river, formed by deposition of sediment during floods.', 22),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is a hydrograph?', 'A graph showing river discharge over time, often in relation to rainfall.', 23),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is lag time?', 'The time between peak rainfall and peak discharge.', 24),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What factors increase flood risk?', 'Heavy rainfall, impermeable rock, steep slopes, urbanisation and deforestation.', 25),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'How does urbanisation increase flood risk?', 'Impermeable surfaces increase surface runoff, and drains carry water quickly to rivers.', 26),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is a flood defence?', 'A structure or strategy to reduce flooding, e.g. dams, embankments, flood relief channels.', 27),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is a flood relief channel?', 'An artificial channel that diverts water away from a town when river levels are high.', 28),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is river restoration?', 'Returning a river to a more natural state to reduce flood risk and improve habitats.', 29),
  ('Geography', 'Eduqas', 'gcse', '1.2', 'River Landscapes', 'What is flood zoning?', 'Restricting building on floodplains in areas at high risk of flooding.', 30),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is a glacier?', 'A large mass of ice that moves slowly downhill under gravity.', 1),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is plucking?', 'Ice freezes onto rocks and pulls them away as the glacier moves.', 2),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is abrasion by glaciers?', 'Rocks frozen into the base of the glacier scrape the rock below like sandpaper.', 3),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is freeze–thaw weathering?', 'Water in cracks freezes and expands, widening the crack until the rock breaks.', 4),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is a corrie?', 'An armchair-shaped hollow on a mountainside, formed by glacial erosion; it may contain a lake (tarn).', 5),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is an arête?', 'A sharp, knife-edge ridge between two corries.', 6),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is a pyramidal peak?', 'A sharp mountain peak formed when three or more corries erode back to back.', 7),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is a U-shaped valley?', 'A wide, flat-bottomed valley with steep sides, formed by a glacier.', 8),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is a truncated spur?', 'A cut-off end of a spur, eroded by a glacier as it moved down the valley.', 9),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is a hanging valley?', 'A small valley left high above a main glacial valley, often with a waterfall.', 10),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is a ribbon lake?', 'A long, narrow lake in the bottom of a U-shaped valley.', 11),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is moraine?', 'Rocks and sediment deposited by a glacier.', 12),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is a terminal moraine?', 'A ridge of material marking the furthest point reached by a glacier.', 13),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is lateral moraine?', 'Material deposited along the sides of a glacier.', 14),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is a drumlin?', 'An egg-shaped hill of glacial deposits, with a blunt end facing the direction the ice came from.', 15),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is an erratic?', 'A boulder carried by a glacier and deposited in an area with different rock.', 16),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is till?', 'Unsorted sediment deposited by a glacier.', 17),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'Where are glaciated landscapes found in the UK?', 'In upland areas such as the Lake District, Snowdonia and the Scottish Highlands.', 18),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What was the last glacial period?', 'The most recent ice age, which ended about 10,000 years ago.', 19),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'How is glaciated land used?', 'Farming (sheep), tourism, forestry, quarrying, and hydroelectric power.', 20),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What are the impacts of tourism in glaciated areas?', 'Jobs and income, but also footpath erosion, traffic congestion and litter.', 21),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is footpath erosion?', 'Damage to paths from many walkers, removing vegetation and exposing soil.', 22),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'How can footpath erosion be managed?', 'Laying stone paths, fencing off areas, and signs to keep walkers on paths.', 23),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is a honeypot site?', 'A popular tourist location that attracts large numbers of visitors.', 24),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What conflicts can occur in glaciated areas?', 'Between farmers, tourists, conservationists and residents over land use.', 25),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is a national park?', 'A protected area of countryside managed for conservation and recreation.', 26),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'Why are glaciers retreating?', 'Global warming is melting ice faster than it accumulates.', 27),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is a glacial trough?', 'Another name for a U-shaped valley.', 28),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is a tarn?', 'A small lake in a corrie.', 29),
  ('Geography', 'Eduqas', 'gcse', '1.3', 'Glaciated Landscapes', 'What is the difference between erosion and weathering?', 'Weathering breaks down rock in place; erosion wears it away and moves it.', 30),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is weather?', 'The day-to-day conditions of the atmosphere, such as temperature, rainfall and wind.', 1),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is climate?', 'The average weather conditions of a place over a long period (usually 30 years).', 2),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is a high-pressure system?', 'An area of sinking air, bringing settled, dry weather (an anticyclone).', 3),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is a low-pressure system?', 'An area of rising air, bringing cloudy, wet and windy weather (a depression).', 4),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What weather does an anticyclone bring in summer?', 'Hot, dry, sunny weather.', 5),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What weather does an anticyclone bring in winter?', 'Cold, clear days, frosty nights and fog.', 6),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is a depression?', 'A low-pressure weather system that brings wind and rain.', 7),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is a warm front?', 'The boundary where warm air rises over cold air, bringing steady rain.', 8),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is a cold front?', 'The boundary where cold air pushes under warm air, bringing heavy rain and gusty winds.', 9),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is an air mass?', 'A large body of air with similar temperature and moisture.', 10),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is a maritime air mass?', 'An air mass that has travelled over the sea, bringing moist air.', 11),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is a continental air mass?', 'An air mass that has travelled over land, bringing dry air.', 12),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is the UK''s climate like?', 'Temperate maritime: mild winters, cool summers, and rain throughout the year.', 13),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'Why is western Britain wetter than eastern Britain?', 'Prevailing south-westerly winds bring moist air from the Atlantic, which rises over western hills (relief rainfall).', 14),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is relief rainfall?', 'Rain caused when air is forced to rise over high ground, cools and condenses.', 15),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is convectional rainfall?', 'Rain caused when the ground heats up, warm air rises, cools and condenses.', 16),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is frontal rainfall?', 'Rain caused when warm air meets cold air and is forced to rise.', 17),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is the North Atlantic Drift?', 'A warm ocean current that keeps the UK milder than other places at the same latitude.', 18),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is global atmospheric circulation?', 'The worldwide movement of air in cells (Hadley, Ferrel and Polar), which creates climate zones.', 19),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is the Hadley cell?', 'The circulation cell between the equator and about 30°, creating rainforests and deserts.', 20),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'Why is there low pressure at the equator?', 'Intense heating makes air rise.', 21),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'Why are deserts found at about 30° north and south?', 'Air sinks there, creating high pressure and dry conditions.', 22),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is a tropical storm?', 'An intense low-pressure system with very strong winds and heavy rain, forming over warm oceans.', 23),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What conditions are needed for a tropical storm to form?', 'Ocean temperatures above 27 °C, low wind shear, and being at least 5° from the equator.', 24),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is extreme weather?', 'Weather that is much more severe than usual, e.g. heatwaves, floods and storms.', 25),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'Give an example of extreme weather in the UK.', 'Storm Desmond (2015), the 2022 heatwave, or the Somerset Levels floods (2014).', 26),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is a heatwave?', 'A period of unusually hot weather.', 27),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is drought?', 'A long period with much less rainfall than normal.', 28),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is microclimate?', 'The climate of a small area that differs from the surrounding area, e.g. an urban heat island.', 29),
  ('Geography', 'Eduqas', 'gcse', '1.4', 'Weather & Climate', 'What is an urban heat island?', 'A city that is warmer than the surrounding countryside due to buildings, roads and human activity.', 30),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What is an ecosystem?', 'A community of living things interacting with each other and their non-living environment.', 1),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What is a biome?', 'A large-scale ecosystem, e.g. tropical rainforest or hot desert.', 2),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'Where are tropical rainforests found?', 'Near the equator, e.g. the Amazon, Congo Basin and Southeast Asia.', 3),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What is the climate of a tropical rainforest?', 'Hot (about 27 °C) and wet all year, with over 2000 mm of rain.', 4),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What are the layers of the rainforest?', 'Emergent layer, canopy, understorey and forest floor.', 5),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What is the canopy?', 'The dense layer of tree tops that absorbs most sunlight.', 6),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What are buttress roots?', 'Large roots that support tall trees in shallow soils.', 7),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What are drip tips?', 'Pointed leaves that allow heavy rain to run off quickly.', 8),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What are lianas?', 'Woody vines that climb trees to reach sunlight.', 9),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What are epiphytes?', 'Plants that grow on other plants to reach light, e.g. orchids.', 10),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'How are animals adapted to the rainforest?', 'E.g. sloths move slowly and are camouflaged; monkeys have prehensile tails; frogs have sticky feet.', 11),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What is the nutrient cycle in rainforests?', 'Nutrients are rapidly recycled from leaf litter to plants, so the soil is poor.', 12),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'Why is rainforest soil infertile?', 'Heavy rain washes nutrients away (leaching), and nutrients are held in plants.', 13),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What is biodiversity?', 'The variety of living things in an area.', 14),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'Why do rainforests have high biodiversity?', 'Warm, wet climate all year allows plants to grow quickly, providing many habitats.', 15),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What is deforestation?', 'The cutting down or removal of forests.', 16),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What are the causes of deforestation?', 'Logging, cattle ranching, farming (e.g. palm oil and soya), mining, road building and hydroelectric dams.', 17),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What are the impacts of deforestation?', 'Loss of biodiversity, soil erosion, climate change, and loss of indigenous people''s homes.', 18),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'How does deforestation contribute to climate change?', 'Trees store carbon; burning or cutting them releases CO₂, and fewer trees absorb CO₂.', 19),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What is sustainable forestry?', 'Managing forests so trees are replanted and the forest can continue to provide resources.', 20),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What is selective logging?', 'Only cutting down some mature trees, leaving the rest of the forest intact.', 21),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What is ecotourism?', 'Tourism that conserves the environment and benefits local people.', 22),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What is agroforestry?', 'Growing crops and trees together, protecting soil and providing resources.', 23),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What is debt-for-nature swap?', 'A country''s debt is reduced in exchange for protecting its rainforest.', 24),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What role do indigenous people play in rainforests?', 'They often live sustainably and help protect forests from exploitation.', 25),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What is a food web?', 'A diagram showing how feeding relationships are linked in an ecosystem.', 26),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What is a producer?', 'An organism that makes its own food through photosynthesis, e.g. plants.', 27),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What is a consumer?', 'An organism that eats other organisms.', 28),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'What is a decomposer?', 'An organism that breaks down dead material, releasing nutrients, e.g. fungi and bacteria.', 29),
  ('Geography', 'Eduqas', 'gcse', '1.5', 'Tropical Rainforests', 'Why is the Amazon rainforest important globally?', 'It stores carbon, regulates climate, has huge biodiversity, and provides medicines.', 30),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What is a hot desert?', 'An area with very low rainfall (under 250 mm a year) and high daytime temperatures.', 1),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'Where are hot deserts found?', 'Around 30° north and south of the equator, e.g. the Sahara and Thar deserts.', 2),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What is the climate of a hot desert?', 'Very hot days, cold nights and very little rainfall.', 3),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'Why are desert nights cold?', 'Clear skies allow heat to escape quickly.', 4),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'How are plants adapted to hot deserts?', 'Cacti store water, have spines instead of leaves, and have long or wide roots.', 5),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'How are animals adapted to hot deserts?', 'Camels store fat in humps and have wide feet; many animals are nocturnal.', 6),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What is desert soil like?', 'Sandy or stony, dry, and low in nutrients.', 7),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What is desertification?', 'The process by which land becomes desert-like due to climate change and human activity.', 8),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What are the causes of desertification?', 'Overgrazing, overcultivation, deforestation, population growth and climate change.', 9),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'Where is desertification a problem?', 'In semi-arid areas such as the Sahel in Africa.', 10),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'How can desertification be reduced?', 'Planting trees, water conservation, appropriate technology, and improving farming methods.', 11),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What are magic stones (bunds)?', 'Lines of stones that slow water runoff and trap soil, reducing erosion.', 12),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What opportunities do hot deserts offer?', 'Mining, energy (solar), farming with irrigation, and tourism.', 13),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What challenges do hot deserts present?', 'Extreme temperatures, water shortages, and poor accessibility.', 14),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What is irrigation?', 'Artificially watering crops.', 15),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What is solar energy''s potential in deserts?', 'Deserts receive lots of sunshine, making them ideal for solar power plants.', 16),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What is the Great Green Wall?', 'A project to plant a belt of trees across the Sahel to stop desertification.', 17),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What is an oasis?', 'A fertile area in a desert where water is found.', 18),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What is a nomad?', 'A person who moves from place to place with their animals to find food and water.', 19),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What is overgrazing?', 'When too many animals graze an area, removing vegetation and exposing soil.', 20),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What is overcultivation?', 'When land is farmed too intensively, exhausting the soil.', 21),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'Why are desert ecosystems fragile?', 'Low rainfall and extreme conditions mean they recover slowly from damage.', 22),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What is biodiversity like in hot deserts?', 'Lower than rainforests, but many species are specially adapted.', 23),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'How does climate change affect hot deserts?', 'Higher temperatures and less rainfall may make them hotter and drier, expanding their area.', 24),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What is a sand dune in a desert?', 'A hill of sand shaped by the wind.', 25),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What is the water cycle like in deserts?', 'Low rainfall and high evaporation mean little water is stored.', 26),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What is the role of tourism in deserts?', 'It provides jobs and income, but can put pressure on water and fragile environments.', 27),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What is mining''s impact in deserts?', 'It provides jobs and resources but uses water and can damage landscapes.', 28),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What is the Thar Desert?', 'A hot desert in north-west India and Pakistan.', 29),
  ('Geography', 'Eduqas', 'gcse', '1.6', 'Hot Deserts', 'What is the Sahel?', 'A semi-arid region south of the Sahara, at risk of desertification.', 30),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Urbanisation & Urban Change', 'What is urbanisation?', 'The increase in the proportion of people living in towns and cities.', 1),
