  ('Geography', 'Eduqas', 'gcse', '2.1', 'Urbanisation & Urban Change', 'What is counter-urbanisation?', 'The movement of people from cities to rural areas.', 14),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Urbanisation & Urban Change', 'What is re-urbanisation?', 'The movement of people back into city centres, often after regeneration.', 15),
