  ('Geography', 'Eduqas', 'gcse', '2.1', 'Urbanisation & Urban Change', 'What is urban sprawl?', 'The spread of cities into the surrounding countryside.', 18),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Urbanisation & Urban Change', 'What is a brownfield site?', 'Previously developed land that can be reused.', 19),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Urbanisation & Urban Change', 'What is a greenfield site?', 'Land that hasn''t been built on before.', 20),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Urbanisation & Urban Change', 'What is a sustainable city?', 'A city that meets people''s needs without damaging the environment for future generations.', 21),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Urbanisation & Urban Change', 'Give an example of a sustainable urban feature.', 'Public transport, green spaces, recycling schemes and energy-efficient buildings.', 22),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Urbanisation & Urban Change', 'What is the CBD?', 'The central business district, the commercial centre of a city.', 23),
  ('Geography', 'Eduqas', 'gcse', '2.1', 'Urbanisation & Urban Change', 'What is the inner city?', 'The area around the CBD, often with older housing and industry.', 24),
