  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'What is the structure of the Earth?', 'Crust, mantle, outer core and inner core.', 1),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'What is a tectonic plate?', 'A large section of the Earth''s crust that moves slowly on the mantle.', 2),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'What causes plates to move?', 'Convection currents in the mantle, and slab pull.', 3),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'What is a destructive plate margin?', 'Where an oceanic plate is forced under a continental plate, causing earthquakes and violent volcanoes.', 4),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'What is a constructive plate margin?', 'Where plates move apart and magma rises to form new crust, causing gentle volcanoes.', 5),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'What is a conservative plate margin?', 'Where plates slide past each other, causing earthquakes but no volcanoes.', 6),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'What is a collision margin?', 'Where two continental plates collide, forming fold mountains.', 7),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'What is the focus of an earthquake?', 'The point underground where the earthquake starts.', 8),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'What is the epicentre?', 'The point on the surface directly above the focus.', 9),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'How are earthquakes measured?', 'Using the moment magnitude scale (or Richter scale) and a seismometer.', 10),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'What is a composite volcano?', 'A steep-sided volcano made of layers of ash and lava, with explosive eruptions.', 11),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'What is a shield volcano?', 'A wide, gently sloping volcano made of runny lava, with gentle eruptions.', 12),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'What is a hotspot?', 'An area of volcanic activity away from plate margins, e.g. Hawaii.', 13),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'What are the primary effects of earthquakes?', 'Buildings collapse, roads and bridges are damaged, and people are killed or injured.', 14),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'What are the secondary effects of earthquakes?', 'Fires, tsunamis, landslides, disease, and homelessness.', 15),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'What is a tsunami?', 'A large sea wave caused by an earthquake under the ocean.', 16),
