  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'How can volcanic eruptions be predicted?', 'Monitoring ground swelling, gas emissions and small earthquakes.', 22),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'Why do earthquakes have more impact in poorer countries?', 'Poor-quality buildings, fewer emergency services, and less preparation.', 23),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'Give an example of an earthquake in a richer country.', 'Japan (Tōhoku 2011) or Christchurch, New Zealand (2011).', 24),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'Give an example of an earthquake in a poorer country.', 'Nepal (2015) or Haiti (2010).', 25),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'What is the Pacific Ring of Fire?', 'A zone around the Pacific Ocean with many volcanoes and earthquakes.', 26),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'What is a pyroclastic flow?', 'A fast-moving cloud of hot gas, ash and rock.', 27),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'What is a lahar?', 'A mudflow of volcanic material mixed with water.', 28),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'What is hazard mapping?', 'Mapping areas at risk from hazards to plan land use and evacuation.', 29),
  ('Geography', 'Eduqas', 'gcse', '3.1', 'Tectonic Hazards', 'What is the magnitude of an earthquake?', 'A measure of the energy released by an earthquake.', 30),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What is climate change?', 'A long-term change in the Earth''s climate, including temperature and rainfall patterns.', 1),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What is the greenhouse effect?', 'Gases in the atmosphere trap heat from the Sun, keeping the Earth warm.', 2),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What is the enhanced greenhouse effect?', 'Human activities increase greenhouse gases, trapping more heat and causing global warming.', 3),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'Name three greenhouse gases.', 'Carbon dioxide, methane and nitrous oxide.', 4),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What are the human causes of climate change?', 'Burning fossil fuels, deforestation, farming (methane from cattle), and industry.', 5),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What are the natural causes of climate change?', 'Changes in the Earth''s orbit, volcanic eruptions and variations in solar output.', 6),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What is the evidence for climate change?', 'Rising global temperatures, melting ice caps, rising sea levels, and ice core records.', 7),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What do ice cores show?', 'Air bubbles trapped in ice show past levels of CO₂ and temperature.', 8),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What are the effects of climate change on the environment?', 'Rising sea levels, melting ice, more extreme weather, and loss of habitats.', 9),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What are the effects of climate change on people?', 'Flooding, food shortages, water shortages, and health problems.', 10),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What is mitigation?', 'Reducing the causes of climate change, e.g. cutting emissions.', 11),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What is adaptation?', 'Changing how we live to cope with the effects of climate change.', 12),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'Give examples of mitigation.', 'Renewable energy, planting trees, carbon capture, and international agreements.', 13),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'Give examples of adaptation.', 'Flood defences, drought-resistant crops, and changing farming practices.', 14),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What is carbon capture and storage?', 'Capturing CO₂ from power stations and storing it underground.', 15),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What is the Paris Agreement?', 'A 2015 international agreement to limit global warming to well below 2 °C.', 16),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What is a carbon footprint?', 'The total amount of greenhouse gases produced by a person, organisation or activity.', 17),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'How can individuals reduce their carbon footprint?', 'Using public transport, saving energy, recycling, and eating less meat.', 18),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'How does climate change affect the UK?', 'Hotter summers, wetter winters, more flooding and rising sea levels.', 19),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'How does climate change affect poorer countries?', 'They are often more vulnerable to droughts, floods and storms, with fewer resources to adapt.', 20),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What is sea-level rise caused by?', 'Melting ice sheets and glaciers, and thermal expansion of water.', 21),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What is thermal expansion?', 'Water expanding as it warms, raising sea levels.', 22),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What is the Quaternary period?', 'The last 2.6 million years, with glacial and interglacial periods.', 23),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What is an interglacial period?', 'A warmer period between glacial periods.', 24),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'How does deforestation contribute to climate change?', 'Trees absorb CO₂; removing them increases CO₂ in the atmosphere.', 25),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What is the role of methane in climate change?', 'Methane is a powerful greenhouse gas released by cattle, rice farming and landfill.', 26),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What is renewable energy?', 'Energy from sources that won''t run out, e.g. wind, solar and hydroelectric power.', 27),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What is a climate refugee?', 'Someone forced to move because of the effects of climate change.', 28),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'How do rising temperatures affect ecosystems?', 'Species may move, adapt or become extinct, e.g. coral bleaching.', 29),
  ('Geography', 'Eduqas', 'gcse', '3.2', 'Climate Change', 'What is coral bleaching?', 'Corals expel algae when water is too warm, turning white and possibly dying.', 30),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is water security?', 'Having reliable access to enough safe, clean water.', 1),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is water scarcity?', 'When there isn''t enough water to meet demand.', 2),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is physical water scarcity?', 'Not enough water available because of the climate or overuse.', 3),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is economic water scarcity?', 'Water is available but people can''t afford the infrastructure to access it.', 4),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'Why is demand for water increasing?', 'Population growth, economic development, and increased use in farming and industry.', 5),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'Where is water surplus in the UK?', 'The north and west, which have high rainfall and low population.', 6),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'Where is water deficit in the UK?', 'The south-east, which has lower rainfall and high population.', 7),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is a water transfer scheme?', 'Moving water from areas of surplus to areas of deficit.', 8),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is a reservoir?', 'An artificial lake used to store water.', 9),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What are the advantages of dams and reservoirs?', 'Water supply, hydroelectric power, flood control and recreation.', 10),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What are the disadvantages of dams and reservoirs?', 'Flooding of land and homes, loss of habitats, and high costs.', 11),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is desalination?', 'Removing salt from seawater to make fresh water.', 12),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is a disadvantage of desalination?', 'It is expensive and uses a lot of energy.', 13),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is groundwater?', 'Water stored underground in rocks (aquifers).', 14),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is water conservation?', 'Reducing water use, e.g. using water meters, efficient appliances and fixing leaks.', 15),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is greywater recycling?', 'Reusing water from sinks, showers and washing machines for flushing toilets or watering gardens.', 16),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is rainwater harvesting?', 'Collecting and storing rainwater for use.', 17),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'How does farming affect water supply?', 'Irrigation uses large amounts of water, and fertilisers can pollute rivers.', 18),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is water pollution?', 'Contamination of water by chemicals, sewage or waste.', 19),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is a water-borne disease?', 'A disease spread through contaminated water, e.g. cholera and typhoid.', 20),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'How can water supply be improved in poorer countries?', 'Wells, hand pumps, rainwater harvesting and water purification.', 21),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is a sustainable water supply?', 'Using water in a way that meets current needs without harming future supply.', 22),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is the water cycle?', 'The continuous movement of water between the sea, air and land.', 23),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is evaporation?', 'Water changing from liquid to gas.', 24),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is condensation?', 'Water vapour cooling and changing into liquid, forming clouds.', 25),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is precipitation?', 'Water falling from clouds as rain, snow, sleet or hail.', 26),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is infiltration?', 'Water soaking into the soil.', 27),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is surface runoff?', 'Water flowing over the ground into rivers.', 28),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is water stress?', 'When demand for water exceeds the available supply.', 29),
  ('Geography', 'Eduqas', 'gcse', '3.3', 'Water Management', 'What is a water conflict?', 'A dispute between groups or countries over access to water, e.g. over the Nile.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Geography' AND exam_board = 'Eduqas' AND level = 'gcse'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;
